// 本日と今週、今月の統計を計算
const trades = $input.all();
const now = new Date();
const today = now.toISOString().split('T')[0];

// 週の開始日（月曜日）を計算
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - now.getDay() + (now.getDay() === 0 ? -6 : 1));
const weekStartStr = weekStart.toISOString().split('T')[0];

// 月の開始日
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
const monthStartStr = monthStart.toISOString().split('T')[0];

function analyzeTradesInPeriod(trades, startDate) {
  const filtered = trades.filter(t => {
    const tradeDate = t.json['日時'] ? t.json['日時'].split('T')[0] : '';
    return tradeDate >= startDate;
  });

  let wins = 0;
  let losses = 0;
  let totalProfit = 0;
  let bestTrade = { profit: -Infinity, symbol: '' };
  let worstTrade = { profit: Infinity, symbol: '' };

  filtered.forEach(trade => {
    const profit = parseFloat(trade.json['損益額']) || 0;
    const symbol = trade.json['通貨ペア'] || '';

    totalProfit += profit;

    if (profit >= 0) {
      wins++;
    } else {
      losses++;
    }

    if (profit > bestTrade.profit) {
      bestTrade = { profit, symbol, date: trade.json['日時'] };
    }

    if (profit < worstTrade.profit) {
      worstTrade = { profit, symbol, date: trade.json['日時'] };
    }
  });

  const total = wins + losses;
  const winRate = total > 0 ? (wins / total * 100).toFixed(2) : 0;

  return {
    total,
    wins,
    losses,
    winRate,
    totalProfit: totalProfit.toFixed(2),
    bestTrade,
    worstTrade
  };
}

const todayStats = analyzeTradesInPeriod(trades, today);
const weekStats = analyzeTradesInPeriod(trades, weekStartStr);
const monthStats = analyzeTradesInPeriod(trades, monthStartStr);

// 通貨ペア別の統計
const symbolStats = {};
trades.slice(1).forEach(trade => {
  const symbol = trade.json['通貨ペア'];
  const profit = parseFloat(trade.json['損益額']) || 0;

  if (!symbolStats[symbol]) {
    symbolStats[symbol] = { count: 0, profit: 0, wins: 0 };
  }

  symbolStats[symbol].count++;
  symbolStats[symbol].profit += profit;
  if (profit >= 0) symbolStats[symbol].wins++;
});

// 通貨ペアを収益順にソート
const topSymbols = Object.entries(symbolStats)
  .sort((a, b) => b[1].profit - a[1].profit)
  .slice(0, 5)
  .map(([symbol, stats]) => ({
    symbol,
    count: stats.count,
    profit: stats.profit.toFixed(2),
    winRate: ((stats.wins / stats.count) * 100).toFixed(2)
  }));

return [{
  json: {
    today: todayStats,
    week: weekStats,
    month: monthStats,
    topSymbols: topSymbols,
    reportDate: now.toISOString(),
    reportDateJP: now.toLocaleDateString('ja-JP', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric',
      weekday: 'long'
    })
  }
}];
